def transform(grid):
    result = [row[:] for row in grid]
    bg = grid[0][0]

    # First pass: horizontal 3-value patterns
    for r in range(len(grid)):
        # Find all non-bg cells in this row
        pattern_cells = [(c, grid[r][c]) for c in range(len(grid[r])) if grid[r][c] != bg]
        if len(pattern_cells) >= 2:
            # Check if all non-bg cells have the same value
            if len(set(val for c, val in pattern_cells)) == 1:
                # All non-bg cells have the same value - fill between
                val = pattern_cells[0][1]
                min_c = pattern_cells[0][0]
                max_c = pattern_cells[-1][0]
                for c in range(min_c + 1, max_c):
                    result[r][c] = val
            else:
                # Mixed values - mark positions that are between same-valued cells
                # For each pair of adjacent cells with same value, fill between
                seen_2 = set()
                for i in range(len(pattern_cells) - 1):
                    (c1, v1), (c2, v2) = pattern_cells[i], pattern_cells[i + 1]
                    if v1 == v2:
                        for c in range(c1 + 1, c2):
                            seen_2.add(c)
                for i in range(len(pattern_cells) - 1, 0, -1):
                    (c1, v1), (c2, v2) = pattern_cells[i - 1], pattern_cells[i]
                    if v1 == v2:
                        for c in range(c1 + 1, c2):
                            seen_2.add(c)

    # Second pass: vertical patterns
    for c in range(len(grid[0])):
        # Find all non-bg cells in this column
        pattern_cells = [(r, grid[r][c]) for r in range(len(grid)) if grid[r][c] != bg]
        if len(pattern_cells) >= 2:
            if len(set(val for r, val in pattern_cells)) == 1:
                val = pattern_cells[0][1]
                min_r = pattern_cells[0][0]
                max_r = pattern_cells[-1][0]
                for r in range(min_r + 1, max_r):
                    result[r][c] = val
            else:
                seen_2 = set()
                for i in range(len(pattern_cells) - 1):
                    (r1, v1), (r2, v2) = pattern_cells[i], pattern_cells[i + 1]
                    if v1 == v2:
                        for r in range(r1 + 1, r2):
                            seen_2.add(r)

    return result

