    for r in range(len(grid)):
        non_bg = [(c, grid[r][c]) for c in range(len(grid[r])) if grid[r][c] != bg]
        if len(non_bg) >= 2:
            if len(set(v for _, v in non_bg)) == 1:
                val = non_bg[0][1]
