                for i in range(len(non_bg) - 1):
                    c1, c2 = non_bg[i][0], non_bg[i + 1][0]
                    for c in range(c1 + 1, c2):
                        if result[r][c] == bg:
                            result[r][c] = fill_val

    # Vertical: same
    for c in range(len(grid[0])):
        non_bg = [(r, grid[r][c]) for r in range(len(grid)) if grid[r][c] != bg]
        if len(non_bg) >= 2:
            if len(set(v for r, v in non_bg)) == 1:
                for i in range(len(non_bg) - 1):
                    r1, r2 = non_bg[i][0], non_bg[i + 1][0]
                    for r in range(r1 + 1, r2):
                        if result[r][c] == bg:
                            result[r][c] = fill_val

    return result

