    bg = grid[0][0]

    has_2_horizontal = [[False]*21 for _ in range(18)]
    has_2_vertical = [[False]*21 for _ in range(18)]

    for r in range(18):
        non_bg = [(c, grid[r][c]) for c in range(21) if grid[r][c] != bg]
        if len(non_bg) >= 2 and len(set(v for _, v in non_bg)) == 1:
            for i in range(len(non_bg) - 1):
                c1, c2 = non_bg[i][0], non_bg[i + 1][0]
                for c in range(c1 + 1, c2):
                    has_2_horizontal[r][c] = True

    for c in range(21):
        non_bg = [(r, grid[r][c]) for r in range(18) if grid[r][c] != bg]
        if len(non_bg) >= 2 and len(set(v for r, v in non_bg)) == 1:
            for i in range(len(non_bg) - 1):
                r1, r2 = non_bg[i][0], non_bg[i + 1][0]
                for r in range(r1 + 1, r2):
                    has_2_vertical[r][c] = True

    for r in range(18):
        for c in range(21):
            if grid[r][c] == bg and (has_2_horizontal[r][c] or has_2_vertical[r][c]):
                result[r][c] = 2

    return result

